module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output reg [WIDTH-1:0]	rdata
);

reg [ADDR_WIDTH-1:0] wrptr_reg;
reg [ADDR_WIDTH-1:0] wrptr_sync;
reg [ADDR_WIDTH-1:0] rdptr_reg;
reg [ADDR_WIDTH-1:0] rdptr_sync;

wire [ADDR_WIDTH-1:0] wr_gray;
wire [ADDR_WIDTH-1:0] rd_gray;
wire [ADDR_WIDTH-1:0] wr_gray_next;
wire [ADDR_WIDTH-1:0] rd_gray_next;

assign wr_gray = {wrptr_reg[ADDR_WIDTH-2:0], ^wrptr_reg[ADDR_WIDTH-1]};
assign rd_gray = {rdptr_reg[ADDR_WIDTH-2:0], ^rdptr_reg[ADDR_WIDTH-1]};
assign wr_gray_next = {wrptr_reg[ADDR_WIDTH-2:0], ~wrptr_reg[ADDR_WIDTH-1]};
assign rd_gray_next = {rdptr_reg[ADDR_WIDTH-2:0], ~rdptr_reg[ADDR_WIDTH-1]};

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wrptr_reg <= {ADDR_WIDTH{1'b0}};
    end else begin
        wrptr_reg <= wr_gray_next;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rdptr_reg <= {ADDR_WIDTH{1'b0}};
    end else begin
        rdptr_reg <= rd_gray_next;
    end
end

always @(posedge wclk) begin
    wrptr_sync <= wrptr_reg;
end

always @(posedge rclk) begin
    rdptr_sync <= rdptr_reg;
end

assign wfull = (wr_gray_next == rd_gray_next) && (wr_gray_next != 0);
assign rempty = (wr_gray == rd_gray);

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rdata <= {WIDTH{1'b0}};
    end else begin
        rdata <= mem[rdptr_sync];
    end
end

reg [WIDTH-1:0] mem [0:DEPTH-1];

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
